-- Name: graphql(text, text, jsonb, jsonb); Type: FUNCTION; Schema: graphql_public; Owner: supabase_admin
--

CREATE FUNCTION graphql_public.graphql("operationName" text DEFAULT NULL::text, query text DEFAULT NULL::text, variables jsonb DEFAULT NULL::jsonb, extensions jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;


ALTER FUNCTION graphql_public.graphql("operationName" text, query text, variables jsonb, extensions jsonb) OWNER TO supabase_admin;

--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: check_visit_promotor_update_integrity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_visit_promotor_update_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_auth_matricula text;
BEGIN
  -- Se for Admin ou Gestor, permite altera??es administrativas
  IF public.is_admin_or_gestor() THEN
    RETURN NEW;
  END IF;

  v_auth_matricula := public.get_auth_promotor_matricula();

  -- Se o usu?rio autenticado n?o possui matr?cula vinculada, pro?be altera??o
  IF v_auth_matricula IS NULL THEN
    RAISE EXCEPTION 'Acesso negado: Usu?rio sem matr?cula de promotor vinculada.';
  END IF;

  -- Se a visita pertencer ? matr?cula autenticada do promotor
  IF OLD.promotor_matricula IS NOT NULL AND OLD.promotor_matricula = v_auth_matricula THEN
    -- 1. Proibir altera??o de chave de rota, loja, ind?stria, matr?cula, data e hor?rio de in?cio
    -- Utilizando consistentemente IS DISTINCT FROM para evitar bypass por valores NULL
    IF NEW.promotor_matricula IS DISTINCT FROM OLD.promotor_matricula THEN
      RAISE EXCEPTION 'Viola??o de seguran?a: N?o ? permitido alterar a matr?cula da visita.';
    END IF;
    IF NEW.loja_codigo IS DISTINCT FROM OLD.loja_codigo THEN
      RAISE EXCEPTION 'Viola??o de seguran?a: N?o ? permitido alterar a loja da visita.';
    END IF;
    IF NEW.industria_codigo IS DISTINCT FROM OLD.industria_codigo THEN
      RAISE EXCEPTION 'Viola??o de seguran?a: N?o ? permitido alterar a ind?stria da visita.';
    END IF;
    IF NEW.rota_id IS DISTINCT FROM OLD.rota_id THEN
      RAISE EXCEPTION 'Viola??o de seguran?a: N?o ? permitido alterar o v?nculo de rota da visita.';
    END IF;
    IF NEW.data_visita IS DISTINCT FROM OLD.data_visita THEN
      RAISE EXCEPTION 'Viola??o de seguran?a: N?o ? permitido alterar a data da visita.';
    END IF;
    IF NEW.started_at IS DISTINCT FROM OLD.started_at THEN
      RAISE EXCEPTION 'Viola??o de seguran?a: N?o ? permitido alterar o hor?rio de in?cio da visita.';
    END IF;

    -- 2. Proibir altera??o ou reabertura de visita que j? foi 'concluida'
    IF OLD.status = 'concluida' THEN
      RAISE EXCEPTION 'Opera??o negada: Visita j? conclu?da n?o pode ser alterada pelo promotor.';
    END IF;

    -- 3. Proibir altera??o de visita marcada como 'nao_realizada'
    IF OLD.status = 'nao_realizada' THEN
      RAISE EXCEPTION 'Opera??o negada: Visita justificada como n?o realizada n?o pode ser alterada pelo promotor.';
    END IF;

    -- 4. Controle estrito de transi??o de status para o promotor:
    -- O promotor s? pode manter 'em_andamento' ou transitar para 'concluida' (checkout)
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NOT (OLD.status = 'em_andamento' AND NEW.status = 'concluida') THEN
        RAISE EXCEPTION 'Viola??o de seguran?a: Transi??o de status inv?lida para o promotor (de % para %).', OLD.status, NEW.status;
      END IF;
    END IF;

    -- 5. Valida??o de completed_at no checkout:
    -- Quando conclu?da, completed_at ? obrigat?rio e n?o pode ser retroativo ao in?cio
    IF NEW.status = 'concluida' THEN
      IF NEW.completed_at IS NULL THEN
        RAISE EXCEPTION 'Opera??o negada: Hor?rio de conclus?o (completed_at) ? obrigat?rio ao concluir a visita.';
      END IF;
      IF OLD.started_at IS NOT NULL AND NEW.completed_at < OLD.started_at THEN
        RAISE EXCEPTION 'Viola??o de integridade: Hor?rio de conclus?o n?o pode ser anterior ao in?cio da visita.';
      END IF;
    END IF;
  ELSE
    -- Se a visita n?o pertence ao promotor autenticado, pro?be muta??o
    RAISE EXCEPTION 'Acesso negado: Voc? s? pode atualizar visitas associadas ? sua pr?pria matr?cula.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_visit_promotor_update_integrity() OWNER TO postgres;

--
-- Name: delete_user_by_admin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_user_by_admin(target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
BEGIN
  -- 1. Validar se o chamador ? um administrador ativo
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Acesso Negado: Apenas administradores podem excluir usu?rios.';
  END IF;

  -- 2. Impedir que o administrador exclua a pr?pria conta em uso
  IF target_user_id = auth.uid() THEN
    RAISE EXCEPTION 'N?o ? poss?vel excluir o pr?prio usu?rio logado.';
  END IF;

  -- 3. Desvincular de hist?rico de importa??es para preservar registros sem violar a FK
  UPDATE public.import_history
  SET imported_by_id = NULL
  WHERE imported_by_id = target_user_id;

  -- 4. Excluir perfil de public.profiles
  DELETE FROM public.profiles WHERE id = target_user_id;

  -- 5. Excluir conta de auth.users
  DELETE FROM auth.users WHERE id = target_user_id;
END;
$$;


ALTER FUNCTION public.delete_user_by_admin(target_user_id uuid) OWNER TO postgres;

