--
-- Name: get_next_industry_code(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_next_industry_code() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $_$
DECLARE
  v_last_val BIGINT;
  v_is_called BOOLEAN;
  next_val BIGINT;
  max_num INT;
BEGIN
  -- Verificar o maior n?mero atual j? persistido
  SELECT COALESCE(
    MAX(
      NULLIF(regexp_replace(codigo, '^IND-0*', ''), '')::INTEGER
    ),
    0
  ) INTO max_num
  FROM public.industrias
  WHERE codigo ~ '^IND-\d+$';

  SELECT s.last_value, s.is_called INTO v_last_val, v_is_called 
  FROM public.industrias_codigo_seq s;

  IF NOT v_is_called THEN
    next_val := v_last_val;
  ELSE
    next_val := v_last_val + 1;
  END IF;

  IF next_val <= max_num THEN
    next_val := max_num + 1;
  END IF;

  RETURN 'IND-' || lpad(next_val::text, 3, '0');
END;
$_$;


ALTER FUNCTION public.get_next_industry_code() OWNER TO postgres;

--
-- Name: get_next_store_code(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_next_store_code() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
  max_num INT;
  next_num INT;
BEGIN
  SELECT COALESCE(
    MAX(
      NULLIF(regexp_replace(codigo, '^LOJ-0*', ''), '')::INTEGER
    ),
    0
  ) INTO max_num
  FROM public.lojas
  WHERE codigo ~ '^LOJ-\d+$';

  IF max_num < 438 THEN
    next_num := 439;
  ELSE
    next_num := max_num + 1;
  END IF;

  RETURN 'LOJ-' || lpad(next_num::text, 4, '0');
END;
$_$;


ALTER FUNCTION public.get_next_store_code() OWNER TO postgres;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, email, name, role, department, status)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', SPLIT_PART(NEW.email, '@', 1)),
    COALESCE(NEW.raw_user_meta_data->>'role', 'operador'),
    COALESCE(NEW.raw_user_meta_data->>'department', 'Opera??es MK9'),
    'ativo'
  )
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email,
    name = COALESCE(EXCLUDED.name, public.profiles.name),
    updated_at = NOW();
  RETURN NEW;
END;
$$;


