--
-- Name: is_promotor_authorized(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_promotor_authorized(p_matricula text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_mode text;
  v_is_auth boolean;
BEGIN
  -- Se a matr?cula for nula ou vazia, n?o est? autorizado
  IF p_matricula IS NULL OR trim(p_matricula) = '' THEN
    RETURN false;
  END IF;

  -- Obter modo atual da tabela system_settings (default: IMPLANTACAO)
  SELECT value INTO v_mode
  FROM public.system_settings
  WHERE key = 'operation_mode';

  -- Se o sistema j? estiver em OPERACAO_OFICIAL, todos os promotores com matr?cula operam normalmente
  IF v_mode = 'OPERACAO_OFICIAL' THEN
    RETURN true;
  END IF;

  -- Se estiver em IMPLANTACAO, verifica se existe autoriza??o ativa com status 'liberado'
  SELECT EXISTS (
    SELECT 1
    FROM public.promoter_operation_authorizations
    WHERE promotor_matricula = p_matricula
      AND status = 'liberado'
  ) INTO v_is_auth;

  RETURN coalesce(v_is_auth, false);
END;
$$;


ALTER FUNCTION public.is_promotor_authorized(p_matricula text) OWNER TO postgres;

--
-- Name: prevent_role_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_role_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
      RAISE EXCEPTION 'Acesso Negado: Apenas administradores podem alterar o papel de permiss?o (role).';
    END IF;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
      RAISE EXCEPTION 'Acesso Negado: Apenas administradores podem alterar o status de acesso.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.prevent_role_change() OWNER TO postgres;

