--
-- Name: profiles Permitir administradores alterarem qualquer perfil; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Permitir administradores alterarem qualquer perfil" ON public.profiles FOR UPDATE TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());


--
-- Name: profiles Permitir administradores criarem perfis; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Permitir administradores criarem perfis" ON public.profiles FOR INSERT TO authenticated WITH CHECK (public.is_admin());


--
-- Name: profiles Permitir atualiza??o do pr?prio perfil; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Permitir atualiza??o do pr?prio perfil" ON public.profiles FOR UPDATE TO authenticated USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));


--
-- Name: profiles Permitir cria??o do pr?prio perfil; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Permitir cria??o do pr?prio perfil" ON public.profiles FOR INSERT TO authenticated WITH CHECK ((auth.uid() = id));


--
-- Name: profiles Permitir leitura de perfis para autenticados; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Permitir leitura de perfis para autenticados" ON public.profiles FOR SELECT TO authenticated USING (true);


--
-- Name: import_history; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE public.import_history ENABLE ROW LEVEL SECURITY;

--
-- Name: import_history import_history_insert_policy; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY import_history_insert_policy ON public.import_history FOR INSERT TO authenticated WITH CHECK (public.is_admin_or_gestor());


--
-- Name: import_history import_history_select_policy; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY import_history_select_policy ON public.import_history FOR SELECT TO authenticated USING (public.is_admin_or_gestor());


--
-- Name: industrias; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE public.industrias ENABLE ROW LEVEL SECURITY;

--
-- Name: industrias industrias_select_policy; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY industrias_select_policy ON public.industrias FOR SELECT TO authenticated USING ((public.is_admin_or_gestor() OR (( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'operador'::text) OR (( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'promotor'::text) OR (codigo = public.get_auth_industria_codigo())));


--
-- Name: industrias industrias_write_policy; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY industrias_write_policy ON public.industrias TO authenticated USING (public.is_admin_or_gestor()) WITH CHECK (public.is_admin_or_gestor());


--
-- Name: lojas; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE public.lojas ENABLE ROW LEVEL SECURITY;

--
-- Name: lojas lojas_select_policy; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY lojas_select_policy ON public.lojas FOR SELECT TO authenticated USING ((public.is_admin_or_gestor() OR (( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'operador'::text) OR (( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'promotor'::text) OR (EXISTS ( SELECT 1
   FROM public.rotas r
  WHERE ((r.loja_codigo = lojas.codigo) AND (r.industria_codigo = public.get_auth_industria_codigo()))))));


--
-- Name: lojas lojas_write_policy; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY lojas_write_policy ON public.lojas TO authenticated USING (public.is_admin_or_gestor()) WITH CHECK (public.is_admin_or_gestor());


--
-- Name: notifications; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

--
-- Name: notifications notifications_select_policy; Type: POLICY; Schema: public; Owner: postgres
--

